from pathlib import Path
import os,subprocess,time
root=Path('/var/render_worker/output/bazzite-godot-gpu-qualification');root.mkdir(exist_ok=True);os.chown(root,1001,1001)
(root/'project.godot').write_text('[application]\nconfig/name="Worker GPU qualification"\n[display]\nwindow/size/viewport_width=128\nwindow/size/viewport_height=128\n[rendering]\nrenderer/rendering_method="gl_compatibility"\n')
(root/'scene.tscn').write_text('[gd_scene load_steps=2 format=3]\n[ext_resource type="Script" path="res://view.gd" id="1"]\n[node name="Capture" type="Node3D"]\nscript = ExtResource("1")\n')
(root/'view.gd').write_text('extends Node3D\nfunc _ready():\n\tvar cube = MeshInstance3D.new()\n\tcube.mesh = BoxMesh.new()\n\tadd_child(cube)\n\tvar cam = Camera3D.new()\n\tadd_child(cam)\n\tcam.position = Vector3(3,3,4)\n\tcam.look_at(Vector3.ZERO)\n\tcam.current = true\n\tvar light = DirectionalLight3D.new()\n\tadd_child(light)\n\tlight.rotation_degrees=Vector3(-45,-30,0)\n\tfor i in range(12):\n\t\tawait get_tree().process_frame\n\tawait RenderingServer.frame_post_draw\n\tvar result=get_viewport().get_texture().get_image().save_png("res://frame.png")\n\tprint("GPU_CAPTURE_RESULT ",result)\n\tget_tree().quit(result)\n')
for f in root.iterdir():os.chown(f,1001,1001)
base=['systemd-run','--quiet','--wait','--pipe','--collect','--unit=watoom-godot-gpu-'+str(time.time_ns()),'-p','MemoryMax=10G','-p','CPUQuota=600%','-p','RuntimeMaxSec=90','--setenv=XDG_RUNTIME_DIR=/run/user/1001','--setenv=WAYLAND_DISPLAY=wayland-0','--','/usr/bin/systemd-inhibit','--what=idle:sleep','--mode=block','--why=Worker-GPU-qualification','/usr/sbin/runuser','-u','watoom','--','flatpak','run','--system','--filesystem=/var/render_worker','org.godotengine.Godot','--path',str(root),'--display-driver','wayland','--rendering-driver','opengl3','--rendering-method','gl_compatibility','res://scene.tscn']
r=subprocess.run(base,capture_output=True,text=True,timeout=110);(root/'qualification.log').write_text(r.stdout+r.stderr);print(r.returncode,r.stdout,r.stderr);assert r.returncode==0 and (root/'frame.png').is_file()
